CREATE ALGORITHM=UNDEFINED DEFINER=`jfiguero`@`%` SQL SECURITY DEFINER VIEW `vw_validated_enrollment_merged` AS with `UniqueTuloy` as (select `enroll_matched_CHED_tbl`.`tuloy_id` AS `tuloy_id` from `enroll_matched_CHED_tbl` where (`enroll_matched_CHED_tbl`.`tuloy_id` is not null) union select `enroll_matched_TESDA_tbl`.`tuloy_id` AS `tuloy_id` from `enroll_matched_TESDA_tbl` where (`enroll_matched_TESDA_tbl`.`tuloy_id` is not null)) select `pa`.`agency_alias` AS `agency_alias`,`ut`.`tuloy_id` AS `tuloy_id`,coalesce(`c`.`match_id`,`t`.`match_id`) AS `match_id`,coalesce(`c`.`member_id`,`t`.`member_id`) AS `member_id` from (((`UniqueTuloy` `ut` left join `enroll_matched_CHED_tbl` `c` on((`c`.`tuloy_id` = `ut`.`tuloy_id`))) left join `enroll_matched_TESDA_tbl` `t` on((`t`.`tuloy_id` = `ut`.`tuloy_id`))) left join `lib_partner_agency` `pa` on((`pa`.`agency_id` = (case when (`c`.`tuloy_id` is not null) then 1 else 2 end))));
